import type { ComponentProps, FC } from "react";
import Transition from "./transition.js";

// ###### CollapseV ######

interface CollapseVProps extends ComponentProps<typeof Transition> {}

export const CollapseVScreen: FC<CollapseVProps> = (props) => {
    return (
        <Transition
            enter="transition-all duration-300 ease-out overflow-hidden"
            enterFrom="max-h-0"
            enterTo="max-h-screen"
            leave="transition-all duration-300 ease-in overflow-hidden"
            leaveFrom="max-h-screen"
            leaveTo="max-h-0"
            {...props}
        />
    );
};

